const jsonInput=document.getElementById("json-input"),jsonOutput=document.getElementById("json-output"),formatBtn=document.getElementById("format-btn"),minifyBtn=document.getElementById("minify-btn"),validateBtn=document.getElementById("validate-btn"),copyBtn=document.getElementById("copy-btn"),clearBtn=document.getElementById("clear-btn");function copyToClipboard(t,e){navigator.clipboard.writeText(t).then(()=>{const t=e.textContent;e.textContent="Copied!",setTimeout(()=>{e.textContent=t},2e3)}).catch(()=>{e.textContent="Failed",setTimeout(()=>{e.textContent="Copy Result"},2e3)})}function resetOutput(){jsonOutput.className="",jsonOutput.style.color=""}let timeout;formatBtn.addEventListener("click",()=>{try{resetOutput();const t=JSON.parse(jsonInput.value);jsonOutput.textContent=JSON.stringify(t,null,2),jsonOutput.className="success"}catch(t){jsonOutput.textContent=`Error: ${t.message}`,jsonOutput.className="error"}}),minifyBtn.addEventListener("click",()=>{try{resetOutput();const t=JSON.parse(jsonInput.value);jsonOutput.textContent=JSON.stringify(t),jsonOutput.className="success"}catch(t){jsonOutput.textContent=`Error: ${t.message}`,jsonOutput.className="error"}}),validateBtn.addEventListener("click",()=>{try{resetOutput(),JSON.parse(jsonInput.value),jsonOutput.textContent="✅Valid JSON!",jsonOutput.className="success"}catch(t){jsonOutput.textContent=`â�Œ Invalid JSON: ${t.message}`,jsonOutput.className="error"}}),copyBtn.addEventListener("click",()=>{copyToClipboard(jsonOutput.textContent,copyBtn)}),clearBtn.addEventListener("click",()=>{jsonInput.value="",jsonOutput.textContent="Your formatted JSON will appear here...",resetOutput()}),jsonInput.addEventListener("input",()=>{clearTimeout(timeout),timeout=setTimeout(()=>{jsonInput.value.trim()&&formatBtn.click()},500)}),document.getElementById("back-to-tools-btn").addEventListener("click",function(t){t.preventDefault(),window.location.href="/#utility-tools-section"});